cat /var/tmp/lab/ident-haiku/results.tsv | awk -F'\t' 'NR>1 && $2 !~ /crash|exp_id/ {
  res = $2 + 0
  mean = $4 + 0

  if (mean > 0.5) branch = "positive"
  else if (mean < -0.5) branch = "negative"
  else branch = "trivial"

  if (!min[branch] || res < min[branch]) {
    min[branch] = res
    id[branch] = $1
  }
}
END {
  for (b in min) {
    print b ":", min[b], "(" id[b] ")"
  }
}' | sort
